Section Case.
  Variable rsh : bvmap 5 word -> Prop.
  Hypothesis rsh_upd : forall (R : bvmap 5 word) (rd : reg) (v : word), bv_eqb rd 0 = false -> rsh R -> rsh (regupd R rd v).
  Variables (regs : bvmap 5 word) (mem rom : word -> option byte) (sp Fb : word) (can : Z).
  Hypothesis SH : snpH mem sp Fb can.
  Hypothesis RSH : rsh regs.
  Hypothesis R2 : getr regs 2 = sp.
  Hypothesis R10 : getr regs 10 = Z_to_bv 64 (bv_unsigned Fb + 32).
  Hypothesis R11 : getr regs 11 = Z_to_bv 64 22.
  Hypothesis R12 : getr regs 12 = Z_to_bv 64 0x252a0.
  Hypothesis R13 : getr regs 13 = Z_to_bv 64 18446744073709551615.
  Hypothesis SP64 : bv_unsigned sp mod 64 = R.
  Let E := snpE regs sp Fb can.

  Lemma sltu0_one' : forall c, 0 < bv_unsigned sp + c < 2 ^ 64 ->
    alu64 ALU_SLTU (Z_to_bv 64 0) (alu64 ALU_ADD sp (Z_to_bv 64 c)) = Z_to_bv 64 1.
  Proof.
    intros c Hc. apply bv_eq. rewrite u_sltu64, u_add64, !u_lit64a. change (0 mod 2 ^ 64) with 0. change (1 mod 2 ^ 64) with 1.
    rewrite Zplus_mod_idemp_r. rewrite Z.mod_small by lia. destruct (Z.ltb_spec 0 (bv_unsigned sp + c)); [reflexivity | lia].
  Qed.
  Ltac closedw :=
    repeat match goal with
    | |- context [sext 64 (alu32 ?op (low32 ?a) (low32 ?b))] =>
        lazymatch constr:((a, b)) with context [sp] => fail | context [Fb] => fail | _ => idtac end;
        let v := eval vm_compute in (bv_unsigned (sext 64 (alu32 op (low32 a) (low32 b)) : word)) in
        replace (sext 64 (alu32 op (low32 a) (low32 b))) with (Z_to_bv 64 v : word) by (apply bv_eq; vm_compute; reflexivity)
    | |- context [alu64 ?op (Z_to_bv 64 ?x) (Z_to_bv 64 ?y)] =>
        let v := eval vm_compute in (bv_unsigned (alu64 op (Z_to_bv 64 x) (Z_to_bv 64 y))) in
        replace (alu64 op (Z_to_bv 64 x) (Z_to_bv 64 y)) with (Z_to_bv 64 v : word) by (apply bv_eq; vm_compute; reflexivity)
    end.
  Ltac arith :=
    cbn [a_base a_off edenot]; change (ev (snpE regs sp Fb can) 0) with sp; change (ev (snpE regs sp Fb can) 1) with Fb;
    rewrite ?sltu0_one' by lia; closedw; bvz; zlits; zmasks; unfold SH0, SHF; Z.div_mod_to_equations; lia.
